        'rules_h' => 'Two things never change',
        'rules' => [
            ['The code is open', 'Every published project makes its code available: anyone can read it, check it, copy it and improve it.'],
            ['Privacy comes first', 'No adverts and no profiling. If an account is not needed, nobody asks for it; if it is, the project page says so before you open the app.'],
